@Configuration public class SeedData {@Bean CommandLineRunner seed(ProductRepository products,UserRepository users,PasswordEncoder encoder,@Value("${ADMIN_EMAIL:}")String adminEmail,@Value("${ADMIN_PASSWORD:}")String adminPassword){return args->{if(products.count()==0){String[][] rows={{"Everyday Stoneware Set","68","Home & Living","Hand-finished ceramic for slow mornings and long dinners.","https://images.unsplash.com/photo-1490312278390-ab64016e0aa9?auto=format&fit=crop&w=1000&q=85","18"},{"Linen Weekend Tote","54","Accessories","A roomy carryall made from European flax linen.","https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=1000&q=85","24"},{"Sculptural Table Lamp","129","Home & Living","Soft, warm light meets an elegant silhouette.","https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=1000&q=85","11"},{"Botanical Hand Wash","24","Bath & Body","A gentle ritual with bergamot, cedar and botanicals.","https://images.unsplash.com/photo-1608571423902-eed4a5ad8108?auto=format&fit=crop&w=1000&q=85","30"},{"The Sunday Throw","96","Home & Living","A soft generous layer woven from recycled cotton.","https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1000&q=85","15"},{"Carry-All Crossbody","88","Accessories","An easy, hands-free companion for the day.","https://images.unsplash.com/photo-1584917865442-de89df76afd3?auto=format&fit=crop&w=1000&q=85","9"},{"Daily Ritual Mug","28","Home & Living","A satisfying little mug with a rounded handle.","https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=1000&q=85","35"},{"Wildflower Candle","36","Bath & Body","Notes of wild stems, green fig and sun-warmed earth.","https://images.unsplash.com/photo-1603006905003-be475563bc59?auto=format&fit=crop&w=1000&q=85","21"}};for(String[]r:rows){Product p=new Product();p.name=r[0];p.price=new BigDecimal(r[1]);p.category=r[2];p.description=r[3];p.imageUrl=r[4];p.stock=Integer.parseInt(r[5]);products.save(p);}}if(!adminEmail.isBlank()&&!adminPassword.isBlank()&&users.findByEmail(adminEmail.toLowerCase()).isEmpty()){User u=new User();u.name="CloudCart Admin";u.email=adminEmail.toLowerCase();u.password=encoder.encode(adminPassword);u.role=Role.ADMIN;users.save(u);}};}}
